template:
use std::sync::mpsc;

fn send_messages() -> (Result<(), mpsc::TrySendError<i32>>, Result<(), mpsc::TrySendError<i32>>) {
    let (tx, _rx) = mpsc::sync_channel(0);
    let r1 = tx.⟦slot1⟧(10);
    let r2 = tx.⟦slot2⟧(20);
    (r1, r2)
}

fn main() {
    let _ = send_messages();
}

tests:
#[test]
fn detects_full_buffer() {
    let (r1, r2) = send_messages();
    assert!(matches!(r1, Err(mpsc::TrySendError::Full(10))));
    assert!(matches!(r2, Err(mpsc::TrySendError::Full(20))));
}
